template <typename T>
T largestOf(T a, T b, T c)
{
    T largest{ a };
    if (b > largest) largest = b;
    if (c > largest) largest = c;
    return largest;
}

template <typename T>
bool isBetween(T value, T low, T high)
{
    return value >= low && value <= high;
}

template <typename T, typename U>
auto addMixed(T a, U b)
{
    return a + b;
}

unitTests:
TEST("largestOf") { CHECK_EQ(largestOf(3, 9, 4), 9); CHECK_NEAR(largestOf(1.5, 0.5, 2.5), 2.5, 1e-12); CHECK_EQ(largestOf('c', 'a', 'b'), 'c'); }
TEST("isBetween") { CHECK(isBetween(5, 1, 10)); CHECK(isBetween(1, 1, 10)); CHECK(!isBetween(11, 1, 10)); CHECK(isBetween(0.5, 0.0, 1.0)); }
TEST("addMixed keeps the decimals") { CHECK_NEAR(addMixed(3, 7.5), 10.5, 1e-12); CHECK_NEAR(addMixed(0.25, 1), 1.25, 1e-12); }
TEST("addMixed with the same types") { CHECK_EQ(addMixed(2, 3), 5); }

